def merge_sorted_streams(*streams):
    import heapq

    # Heap entries: (key, stream_index, iterator, value)
    heap = []
    stream_iters = [iter(s) for s in streams]

    for idx, it in enumerate(stream_iters):
        try:
            key, value = next(it)
            heapq.heappush(heap, (key, idx, it, value))
        except StopIteration:
            pass

    while heap:
        key, idx, it, value = heapq.heappop(heap)
        yield key, value

        try:
            next_key, next_value = next(it)
            heapq.heappush(heap, (next_key, idx, it, next_value))
        except StopIteration:
            pass
